/* ---------- Companions ---------- */

.team-panel {
  position: absolute;
  left: calc(16px + var(--safe-left));
  bottom: calc(17px + var(--safe-bottom));
  width: 286px;
  padding: 9px 11px 10px;
  border-radius: 4px 13px 13px 13px;
  pointer-events: none;
}

.team-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 7px;
  color: var(--gold);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.22em;
}

.team-head b {
  color: rgba(239, 182, 97, 0.65);
  font-size: 8px;
  letter-spacing: 0.1em;
}

.team-list {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.team-empty {
  color: rgba(145, 139, 127, 0.66);
  font-family: var(--serif);
  font-size: 11px;
  font-style: italic;
  line-height: 1.35;
}

.team-card {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 6px 7px;
  border: 1px solid rgba(236, 219, 188, 0.1);
  border-radius: 3px;
  background: rgba(8, 13, 22, 0.55);
}

.tc-dot {
  width: 7px;
  height: 7px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 7px rgba(129, 173, 137, 0.55);
}

.tc-dot.scout { background: #8fb7c4; box-shadow: 0 0 7px rgba(143, 183, 196, 0.55); }
.tc-dot.hunter { background: #d59a5f; box-shadow: 0 0 7px rgba(213, 154, 95, 0.55); }
.tc-dot.medic { background: #9dc3a4; box-shadow: 0 0 7px rgba(157, 195, 164, 0.55); }
.tc-dot.engineer { background: #b9a4c8; box-shadow: 0 0 7px rgba(185, 164, 200, 0.5); }

.tc-main {
  min-width: 0;
  flex: 1;
}

.tc-main b {
  display: block;
  overflow: hidden;
  color: var(--bone);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tc-main span {
  display: block;
  margin-top: 1px;
  overflow: hidden;
  color: var(--muted);
  font-size: 7.5px;
  letter-spacing: 0.04em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tc-hp {
  height: 3px;
  margin-top: 4px;
  overflow: hidden;
  border-radius: 1px;
  background: rgba(236, 219, 188, 0.1);
}

.tc-hp i {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, #6e9b78, #a5c8a9);
  transition: width 0.2s ease;
}

.tc-dismiss {
  display: grid;
  width: 19px;
  height: 19px;
  flex: 0 0 auto;
  padding: 0;
  place-items: center;
  border: 1px solid rgba(236, 219, 188, 0.14);
  border-radius: 50%;
  background: transparent;
  color: rgba(199, 188, 170, 0.55);
  font-size: 10px;
  line-height: 1;
  cursor: pointer;
  pointer-events: auto;
  transition: border-color 0.18s, color 0.18s, background 0.18s;
}

.tc-dismiss:hover,
.tc-dismiss:focus-visible {
  border-color: rgba(239, 182, 97, 0.55);
  background: rgba(78, 55, 27, 0.4);
  color: var(--gold);
}

.sp-occupant {
  margin: -8px 0 11px;
  color: rgba(127, 178, 165, 0.9);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.sp-occupant.empty {
  color: rgba(145, 139, 127, 0.55);
}

body.touch #mobileControls { display: block; }
body.touch #crosshair { display: none; }
body.touch .weapon-box { display: none; }

@media (max-width: 820px) {
  .team-panel {
    left: calc(10px + var(--safe-left));
    bottom: calc(151px + var(--safe-bottom));
    width: 164px;
    padding: 7px 8px 8px;
  }

  .team-head {
    margin-bottom: 5px;
    font-size: 6.5px;
  }

  .team-head b { font-size: 6.5px; }

  .team-empty { font-size: 9px; }

  .team-card {
    gap: 5px;
    padding: 4px 5px;
  }

  .tc-main b { font-size: 7.5px; }
  .tc-main span { font-size: 6.5px; }

  .tc-dot {
    width: 5px;
    height: 5px;
  }

  .tc-dismiss {
    width: 17px;
    height: 17px;
    font-size: 9px;
  }

  .sp-occupant { font-size: 6.5px; }
}

@media (max-height: 600px) and (orientation: landscape) {
  .team-panel {
    bottom: calc(12px + var(--safe-bottom));
    width: 210px;
  }
}

