    centerBanner: $('centerBanner'),
    bannerKicker: $('bannerKicker'),
    bannerTitle: $('bannerTitle'),
    bannerSub: $('bannerSub'),
    teamPanel: $('teamPanel'),
    teamCount: $('teamCount'),
    teamList: $('teamList'),
    joystick: $('joystick'),
    stickNub: $('stickNub'),
    useBtn: $('useBtn'),
    fireBtn: $('fireBtn'),
    crosshair: $('crosshair'),
    damageFlash: $('damageFlash'),
    healFlash: $('healFlash'),
    menuScreen: $('menuScreen'),
    bestDays: $('bestDays'),
    startBtn: $('startBtn'),
    pauseScreen: $('pauseScreen'),
