      ctx.beginPath();
      ctx.ellipse(0, -14 * size, 9 * size, 3.4 * size, 0, 0, TAU);
      ctx.fill();
      ctx.beginPath();
      ctx.arc(0, -15.5 * size, 4.5 * size, 0, TAU);
