      ctx.fillStyle = 'rgba(248,180,90,0.28)';
      ctx.beginPath();
      ctx.arc(-12 * size, 1 * size, 9 * size, 0, TAU);
      ctx.fill();
      ctx.fillStyle = '#ffd08a';
      ctx.beginPath();
      ctx.arc(-12 * size, 1 * size, 2.6 * size, 0, TAU);
      ctx.fill();
