    ctx.restore();
  }

  function drawPlayer() {
    const blink = player.invuln > 0 && Math.floor(game.time * 22) % 2 === 0;
    ctx.save();
    ctx.globalAlpha = blink ? 0.55 : 1;
    ctx.translate(player.x, player.y);
    ctx.fillStyle = 'rgba(2,5,4,0.45)';
