      ctx.beginPath();
      ctx.ellipse(0, 0, 14, 18, 0, 0, TAU);
      ctx.fill();
    }
    if (game.muzzle > 0) {
      const mx = Math.cos(player.aim) * 29;
      const my = Math.sin(player.aim) * 29;
