    ctx.lineCap = 'round';
    for (const b of game.bullets) {
      const friendly = b.owner !== 'player';
      ctx.strokeStyle = friendly ? 'rgba(180,230,190,0.9)' : 'rgba(255,202,120,0.95)';
      ctx.shadowColor = friendly ? 'rgba(130,220,160,0.9)' : 'rgba(255,160,70,0.9)';
      ctx.shadowBlur = 8;
